import { balanceDue } from './payments.js';
import { daysBetween } from './dates.js';
import { roundCents } from './money.js';

/**
 * Get invoices that are overdue as of a given date.
 * @param {Array} invoices - all invoices
 * @param {string} asOf - YYYY-MM-DD format cutoff date
 * @returns {Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }>}
 */
export function overdueInvoices(invoices, asOf) {
  return invoices
    .filter((inv) => inv.status === 'issued' || inv.status === 'partially_paid')
    .filter((inv) => inv.dueDate < asOf)
    .map((inv) => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);
}

/**
 * Summarize VAT collected across invoices, grouped by rate.
 * @param {Array} invoices - all invoices
 * @returns {Array<{ rate: number, base: number, vat: number }>}
 */
export function vatSummary(invoices) {
  const vatByRate = {};

  for (const invoice of invoices) {
    if (invoice.status !== 'issued' && invoice.status !== 'partially_paid' && invoice.status !== 'paid') {
      continue;
    }

    for (const line of invoice.lines) {
      const rate = line.vatRate;
      const total = line.qty * line.unitPrice;
      const discountPercent = line.discountPercent ?? 0;
      const lineDiscount = roundCents(total * discountPercent / 100);
      const lineAmount = total - lineDiscount;
      const lineVat = roundCents(lineAmount * rate / 100);

      if (!vatByRate[rate]) {
        vatByRate[rate] = { base: 0, vat: 0 };
      }
      vatByRate[rate].base += lineAmount;
      vatByRate[rate].vat += lineVat;
    }
  }

  return Object.entries(vatByRate)
    .map(([rate, data]) => ({
      rate: parseInt(rate, 10),
      base: data.base,
      vat: data.vat,
    }))
    .sort((a, b) => b.rate - a.rate);
}

/**
 * Calculate late fee on an invoice as of a given date.
 * Late fee is 0.04% of amount due per day overdue.
 * @param {object} invoice
 * @param {string} asOf - YYYY-MM-DD format cutoff date
 * @returns {number} - late fee in cents, or 0 if not overdue
 */
export function lateFee(invoice, asOf) {
  if (!invoice.dueDate || asOf < invoice.dueDate || asOf === invoice.dueDate) {
    return 0;
  }

  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  const due = balanceDue(invoice);
  const fee = roundCents(daysOverdue * due * 0.0004);

  return Math.max(0, fee);
}

