test('overdueInvoices sorts by daysOverdue descending', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  assert.equal(inv1.ok, true);
  const issued1 = issueInvoice(inv1.value, []);

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  assert.equal(inv2.ok, true);
  const issued2 = issueInvoice(inv2.value, ['INV-2026-0001']);

  const inv3 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  assert.equal(inv3.ok, true);
  const issued3 = issueInvoice(inv3.value, ['INV-2026-0001', 'INV-2026-0002']);

  const result = overdueInvoices([issued1.value, issued2.value, issued3.value], '2026-10-30');
  assert.equal(result.length, 3);
  // inv1: dueDate 2026-10-15, 15 days overdue
  // inv2: dueDate 2026-10-21, 9 days overdue
  // inv3: dueDate 2026-10-19, 11 days overdue
  assert.equal(result[0].number, 'INV-2026-0001');
  assert.equal(result[1].number, 'INV-2026-0003');
  assert.equal(result[2].number, 'INV-2026-0002');
  assert(result[0].daysOverdue >= result[1].daysOverdue);
  assert(result[1].daysOverdue >= result[2].daysOverdue);
});

