test('dashboard topCustomers limited to 3', () => {
  const invoices = [];
  for (let i = 1; i <= 5; i++) {
    const inv = createInvoice({
      customerId: `C-00${i}`,
      issueDate: '2026-10-07',
      lines: [{ sku: 'DEV-HOUR', qty: i }],
    });
    assert.equal(inv.ok, true);
    const issued = issueInvoice(inv.value, invoices.map((x) => x.number).filter(Boolean));
    assert.equal(issued.ok, true);
    invoices.push(issued.value);
  }

  const result = dashboard(invoices, '2026-10-15');
  assert.equal(result.topCustomers.length, 3);
  // Should be customers with highest due amounts
  assert.equal(result.topCustomers[0].customerId, 'C-005');
  assert.equal(result.topCustomers[1].customerId, 'C-004');
  assert.equal(result.topCustomers[2].customerId, 'C-003');
});

